questions.solution:
import math

THRESHOLD = 1000  # dollars


def decide(amount, order_total, refunded):
    """Return "refund", "confirm" or "refuse" for one refund request."""
    if not isinstance(amount, (int, float)) or isinstance(amount, bool):
        return "refuse"
    if not math.isfinite(amount) or amount <= 0:
        return "refuse"
    total = refunded + amount
    if total > order_total:
        return "refuse"
    if total > THRESHOLD:
        return "confirm"
    return "refund"
